func buildClusterImplConfigForDNS(g *nameGenerator, endpoints []resolver.Endpoint, mechanism DiscoveryMechanism) (string, *clusterimpl.LBConfig, []resolver.Endpoint) {
	// Endpoint picking policy for DNS is hardcoded to pick_first.
	const childPolicy = "pick_first"
	retEndpoints := make([]resolver.Endpoint, len(endpoints))
	pName := fmt.Sprintf("priority-%v", g.prefix)
	for i, e := range endpoints {
		// For Logical DNS clusters, the same hostname attribute is added
		// to all endpoints. It is set to the name that is resolved for the
		// Logical DNS cluster, including the port number.
		retEndpoints[i] = xdsresource.SetHostname(hierarchy.SetInEndpoint(e, []string{pName}), mechanism.DNSHostname)
		// Copy the nested address field as slice fields are shared by the
		// iteration variable and the original slice.
		retEndpoints[i].Addresses = append([]resolver.Address{}, e.Addresses...)
	}
	return pName, &clusterimpl.LBConfig{
		Cluster:               mechanism.Cluster,
		TelemetryLabels:       mechanism.TelemetryLabels,
		ChildPolicy:           &internalserviceconfig.BalancerConfig{Name: childPolicy},
		MaxConcurrentRequests: mechanism.MaxConcurrentRequests,
		LoadReportingServer:   mechanism.LoadReportingServer,
	}, retEndpoints
}

// lbConfig is the balancer config for xds routing policy.
type lbConfig struct {
	serviceconfig.LoadBalancingConfig
	Children map[string]childConfig
}

// EnableAutoHostRewrite adds the autoHostRewrite value to the context for
// the xds_cluster_impl LB policy to pick.
func EnableAutoHostRewrite(ctx context.Context) context.Context {
	return context.WithValue(ctx, autoHostRewriteKey{}, true)
}

// XDSConfig holds the complete gRPC client-side xDS configuration containing
// all necessary resources.
type XDSConfig struct {
	// Listener holds the listener configuration. It is guaranteed to be
	// non-nil.
	Listener *ListenerUpdate

	// RouteConfig holds the route configuration. It will be populated even if
	// the route configuration was inlined into the Listener resource. It is
	// guaranteed to be non-nil.
	RouteConfig *RouteConfigUpdate

	// VirtualHost is selected from the route configuration whose domain field
	// offers the best match against the provided dataplane authority. It is
	// guaranteed to be non-nil.
	VirtualHost *VirtualHost

	// Clusters is a map from cluster name to its configuration.
	Clusters map[string]*ClusterResult
}

// ClusterConfig contains configuration for a single cluster.
type ClusterConfig struct {
	// Cluster configuration for the cluster. This field is always set to a
	// non-nil value.
	Cluster *ClusterUpdate
	// EndpointConfig contains endpoint configuration for a leaf cluster. This
	// field is only set for EDS and LOGICAL_DNS clusters.
	EndpointConfig *EndpointConfig
	// AggregateConfig contains configuration for an aggregate cluster. This
	// field is only set for AGGREGATE clusters.
	AggregateConfig *AggregateConfig
}

// LBConfig is the config for cluster resolver balancer.
type LBConfig struct {
	serviceconfig.LoadBalancingConfig `json:"-"`
	// DiscoveryMechanisms is an ordered list of discovery mechanisms.
	//
	// Must have at least one element. Results from each discovery mechanism are
	// concatenated together in successive priorities.
	DiscoveryMechanisms []DiscoveryMechanism `json:"discoveryMechanisms,omitempty"`

	// XDSLBPolicy specifies the policy for locality picking and endpoint picking.
	XDSLBPolicy json.RawMessage `json:"xdsLbPolicy,omitempty"`
	xdsLBPolicy internalserviceconfig.BalancerConfig
}

func SetInEndpoint(endpoint resolver.Endpoint, path []string) resolver.Endpoint {
	endpoint.Attributes = endpoint.Attributes.WithValue(pathKey, pathValue(path))
	return endpoint
}

func SetHostname(endpoint resolver.Endpoint, hostname string) resolver.Endpoint {
	// Only set if non-empty; xds_cluster_impl uses this to trigger :authority
	// rewriting.
	if hostname == "" {
		return endpoint
	}
	endpoint.Attributes = endpoint.Attributes.WithValue(hostnameKeyType{}, hostname)
	return endpoint
}
